import{_ as e,o as a,c as o,a3 as i}from"./chunks/framework.DDTb8brS.js";const h=JSON.parse('{"title":"EP.09 团队协作规范","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.09-team-collaboration.md","filePath":"comics/EP.09-team-collaboration.md","lastUpdated":1792677581000}'),l={name:"comics/EP.09-team-collaboration.md"};function n(r,t,s,d,c,p){return a(),o("div",null,[...t[0]||(t[0]=[i(`<h1 id="ep-09-团队协作规范" tabindex="-1">EP.09 团队协作规范 <a class="header-anchor" href="#ep-09-团队协作规范" aria-label="Permalink to &quot;EP.09 团队协作规范&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../09-team-collaboration">09-team-collaboration.md</a>（9.2 编码规范 / 9.4 Git 工作流 / 9.5 Conventional Commits / 9.7 ADR / 9.8 CODEOWNERS）</p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：像素酱的团队各写各的——有人 4 空格有人 Tab，git log 全是&quot;修复&quot;&quot;调整&quot;，规范只停留在口头上。</li><li><strong>第 2 格</strong>：码叔讲 Conventional Commits：<code>feat/fix/refactor</code> + 作用域 + 描述，机器可读，自动生成 SemVer 版本号和 CHANGELOG；Trunk-Based vs GitFlow 按团队选。</li><li><strong>第 3 格</strong>：标签君实证 ADR（架构决策记录）回答&quot;当时为什么这么选&quot;，CODEOWNERS 管&quot;改哪个模块谁来审&quot;，决策与责任都留痕。</li><li><strong>第 4 格</strong>：码叔结案——规范即代码，写进 detekt/ktlint 配置由 CI 强制执行，不靠自觉。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-规范不落地的常见症状" tabindex="-1">第 1 格 · 规范不落地的常见症状 <a class="header-anchor" href="#第-1-格-·-规范不落地的常见症状" aria-label="Permalink to &quot;第 1 格 · 规范不落地的常见症状&quot;">​</a></h3><ul><li>代码风格因人而异，diff 里全是格式噪音；</li><li>提交信息无意义，无法回溯&quot;这个改动解决了什么问题&quot;；</li><li>规范只存在于 wiki/口头，新人来了没人遵守；</li><li>解法：<strong>规范必须自动化</strong>，进 pre-commit + CI，不通过就不能提交/合并。</li></ul><h3 id="第-2-格-·-conventional-commits" tabindex="-1">第 2 格 · Conventional Commits <a class="header-anchor" href="#第-2-格-·-conventional-commits" aria-label="Permalink to &quot;第 2 格 · Conventional Commits&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;type&gt;(&lt;scope&gt;): &lt;description&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[optional body]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[optional footer(s)]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><table tabindex="0"><thead><tr><th>type</th><th>语义</th><th>SemVer</th></tr></thead><tbody><tr><td><code>feat</code></td><td>新功能</td><td>minor</td></tr><tr><td><code>fix</code></td><td>修复 bug</td><td>patch</td></tr><tr><td><code>refactor</code></td><td>重构（不改变功能）</td><td>—</td></tr><tr><td><code>docs</code></td><td>文档</td><td>—</td></tr><tr><td><code>chore</code></td><td>构建/工具</td><td>—</td></tr><tr><td><code>BREAKING CHANGE</code></td><td>不兼容变更</td><td>major</td></tr></tbody></table><ul><li>工具链：commitlint（校验）+ semantic-release（自动发版）+ release-please（自动 PR）。</li></ul><h3 id="第-3-格-·-adr-与-codeowners" tabindex="-1">第 3 格 · ADR 与 CODEOWNERS <a class="header-anchor" href="#第-3-格-·-adr-与-codeowners" aria-label="Permalink to &quot;第 3 格 · ADR 与 CODEOWNERS&quot;">​</a></h3><p><strong>ADR（Architecture Decision Record）</strong>：每个架构决策一篇 markdown，记录背景、决策、后果、替代方案，存 <code>docs/adr/</code> 目录；</p><ul><li>价值：半年后新人问&quot;为什么用 Hilt 不用 Koin&quot;，翻 ADR 就有答案，不用考古 git blame。</li></ul><p><strong>CODEOWNERS</strong>：<code>.github/CODEOWNERS</code> 声明每个目录的负责团队，PR 自动指派评审人；</p><ul><li>价值：核心模块改动必过对应团队评审，避免&quot;没人审就合了&quot;。</li></ul><h3 id="第-4-格-·-code-review-与持续改进" tabindex="-1">第 4 格 · Code Review 与持续改进 <a class="header-anchor" href="#第-4-格-·-code-review-与持续改进" aria-label="Permalink to &quot;第 4 格 · Code Review 与持续改进&quot;">​</a></h3><ul><li>Code Review 清单：① 功能正确吗？② 测试覆盖了吗？③ 命名清晰吗？④ 有没有更简单的写法？⑤ 是否引入技术债？</li><li>规范要<strong>随业务演进</strong>：每季度回顾一次 detekt 规则和 ADR，过时的及时更新；</li><li>✅ 短分支（&lt; 1 天）+ 频繁合并，避免长寿命分支的合并地狱。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li>Code Review 只挑格式毛病，不看设计和边界条件，review 变成形式主义；</li><li>规范文档写完就不更新，半年后和实际代码完全脱节；</li><li>分支存活超过一周，合并时冲突成堆，谁都不敢 merge。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>Conventional Commits 中 <code>feat</code> 和 <code>fix</code> 分别对应什么 SemVer 版本？——<strong>feat → minor（次版本号+1），fix → patch（修订号+1）</strong>。</li><li>ADR 的作用是什么？——<strong>记录架构决策的背景、决策、后果和替代方案，让团队在数月后仍能理解&quot;当时为什么这么选&quot;</strong>。</li><li>为什么规范必须进 CI 而不是靠自觉？——<strong>人会松懈、会遗忘、会有例外；只有自动化、强制阻断的规范才能长期稳定执行</strong>。</li></ol>`,22)])])}const m=e(l,[["render",n]]);export{h as __pageData,m as default};
